from proto import *
def spir(a0, a1, r0, r1, step=3): return arcpts(lambda a: r0 + (r1-r0)*(a-a0)/(a1-a0), a0, a1, step)
def run(name, tail=(0,-40,35,35), horn=[(27,-26),(24.5,-29.5),(21.5,-27.2)], headE=[], back=-66.5, headW=[], sl=(-148,-174,30,30), north=[P(35,-177)], endR=35):
    Hh = spir(*tail) + horn + headE + headW + spir(*sl) + north + [P(endR,-179.9)]
    F = evaluate(Hh, name); print('   ', deficit(F))
    for z in [-60,-50,-40,-30]: r=np.nonzero(F[z+90])[0]; print('     z',z,'x',r.min()-60, r.max()-59, 'w', r.max()-r.min()+1)
    return F
# b1: the bay bites the head's NE; the head back x -33..+6
run('b1', headE=[(12.7,-29.1),(7,-32.5),(3,-38),(1.5,-45),(3,-51),(6,-56),(7,-61),(6,-66.5)], headW=[(-33,-66.5),(-37,-62),(-39.5,-55),(-40.5,-47),(-40,-39),(-38,-32),(-35,-26.5)])
